public Action inspect(AtmosphereResource r) {
    switch (r.getTransport().name()) {
        case "WEBSOCKET":
            if (!r.getAtmosphereConfig().getMetaBroadcast()) {
                r.suspend(true);
            }
            break;
        case "HTTPPOLL":
            if (r.getAtmosphereConfig().getAutoSuspend()) {
                r.resumeOnBroadcast(false);
            }
            break;
        case "HTTPSTREAM":
            if (r.getAtmosphereConfig().getAutoSuspend() && r.getAtmosphereConfig().getMetaBroadcast()) {
                r.suspend(true);
            }
            break;
        default:
            // no-op
    }
