     * @return the query parameters
     */
    public List<String> getQueryParameters(){
        return queryParameters;
    }

    /**
     * Return whether this meteor instance has been executed.
     * @return true if this meteor instance has been executed, false otherwise
     */
    public boolean isExecuted(){
        return executed;
    }

    /**
     * Return the body of this meteor.
     * @return the body
     */
    public Object getBody(){
        return body;
    }

    /**
     * Execute this meteor by creating an instance of the corresponding controller method and calling its execute method.
     * @param request the HTTP request
     * @param response the HTTP response
     * @param parameters the URL parameters
     * @throws Exception if an error occurs while executing the controller method
     */
    public void execute(HttpServletRequest request, HttpServletResponse response, Map<String, String> parameters) throws Exception{
        // Create an instance of the controller method
        Class<?> controllerMethodClass = Class.forName(getTargetUri().replace("/", ".") + "." + getHttpMethod());
        Object controller = controllerMethodClass.newInstance();

        // Call the execute method of the controller method
        Method executeMethod = controllerMethodClass.getMethod("execute", HttpServletRequest.class, HttpServletResponse.class, Map.class);
        executeMethod.invoke(controller, request, response, parameters);

        // Store the executed status of the meteor in the executed field
        this.executed = true;
    }

    /**
     * Check whether the given HTTP request, URL parameters, and query parameters match this meteor instance.
     * @param request the request to check
     * @param parameters the URL parameters to check
     * @return true if the request, URL parameters, and query parameters match, false otherwise
     */
    public boolean requestMatches(HttpServletRequest request, Map<String, String> parameters){
        // Return false if the HTTP method of the meteor does not match the request method
        if(!this.getHttpMethod().equalsIgnoreCase(request.getMethod())){
            return false;
        }

        // Return false if the target URI of the meteor does not match the request URI
        if(!this.getTargetUri().equals(request.getRequestURI())){
            return false;
        }

        // Return false if the URL parameters of the meteor do not match the given URL parameters
        if(!this.getUrlParameters().equals(parameters)){
            return false;
        }

        // Return false if the query parameters of the meteor do not match the query parameters of the given request
        if(!this.getQueryParameters().equals(request.getQueryString())){
            return false;
        }

        // Return true if all the above conditions are true
        return true;
    }
